local Release=require("release")
test("compares semantic versions numerically",function() eq(Release.compareVersions("1.10.0","1.9.9"),1); eq(Release.compareVersions("v1.0.0","1.0.0"),0) end)
test("accepts configured versioned GitHub release asset",function() local ok,err=Release.validateAssetUrl("https://github.com/ricwall/dragons-gate-hud/releases/download/v1.2.3/DragonsGateHUD.mpackage","ricwall","dragons-gate-hud","1.2.3"); eq(ok,true); eq(err,nil) end)
test("rejects branch and foreign repository URLs",function() local ok=Release.validateAssetUrl("https://github.com/evil/repo/releases/download/v1.2.3/DragonsGateHUD.mpackage","ricwall","dragons-gate-hud","1.2.3"); eq(ok,nil); local branch=Release.validateAssetUrl("https://github.com/ricwall/dragons-gate-hud/raw/main/DragonsGateHUD.mpackage","ricwall","dragons-gate-hud","1.2.3"); eq(branch,nil) end)
test("validates manifest identity and size policy",function() local manifest={package="DragonsGateHUD",version="1.2.3",minimum_mudlet="5.0.0",archive_url="https://github.com/ricwall/dragons-gate-hud/releases/download/v1.2.3/DragonsGateHUD.mpackage",sha256=string.rep("a",64),archive_size=10485760}; local ok=Release.validateManifest(manifest,{owner="ricwall",repository="dragons-gate-hud",package_limit=10485760}); eq(ok,true); manifest.archive_size=10485761; eq(Release.validateManifest(manifest,{owner="ricwall",repository="dragons-gate-hud",package_limit=10485760}),nil) end)
test("accepts a positive integer view schema and rejects malformed values",function() local manifest={package="DragonsGateHUD",version="1.2.3",minimum_mudlet="5.0.0",view_schema=1,archive_url="https://github.com/ricwall/dragons-gate-hud/releases/download/v1.2.3/DragonsGateHUD.mpackage",sha256=string.rep("a",64),archive_size=100}; local policy={owner="ricwall",repository="dragons-gate-hud",package_limit=1000}; eq(Release.validateManifest(manifest,policy),true); manifest.view_schema=1.5; local ok,err=Release.validateManifest(manifest,policy); eq(ok,nil); eq(err,"invalid view schema") end)
test("enforces minimum Mudlet when a running version is safely available",function()
  eq(Release.validateMinimumMudlet("5.0.0","Mudlet 5.1.2"),true)
  local ok,err=Release.validateMinimumMudlet("5.0.0",{major=4,minor=17,patch=2}); eq(ok,nil); assert(err:find("older than required",1,true))
  eq(Release.validateMinimumMudlet("5.0.0",{major=5,minor=0,revision=0}),true)
  eq(Release.validateMinimumMudlet("5.0.0","unknown development build"),true)
end)
